// GEN_OBJ_START::sdr_sm_on_entry_busy
void sdr_sm_on_entry_busy(const uint16_t instance_id, const sState_t * const pSMRoot, const sHSM_EventType_t * const pEvent)
{
    (void) instance_id;
    (void) pSMRoot;
    (void) pEvent;

    // USER_CODE_START::onEntry_busy
    // service operation request, based on operation type
    es_tftp_err_code_t res = ES_TFTP_ERR_NOT_DEFINED;
    switch (sdr_rt_context.sdr_op_req.op)
    {
        case OP_FILE_TRANSFER:
            {
                if (UPLOAD == sdr_rt_context.sdr_ft_req.ft_op)
                {
                    res = sdr_upload(&sdr_rt_context.sdr_ft_req);
                    ES_TRACE_DEBUG("sdr op> [upload] file from SDR -> [%d]", res);
                }
                else if (DOWNLOAD == sdr_rt_context.sdr_ft_req.ft_op)
                {
                    res = sdr_download(&sdr_rt_context.sdr_ft_req);
                    ES_TRACE_DEBUG("sdr op> [download] file from SDR -> [%d]", res);
                }
                else
                {
                    ES_TRACE_ERROR("sdr op> [file transfer] invalid operation");
                    sdr_rt_context.sdr_ft_status = ES_TFTP_ERR_ILLEGAL_TFTP_OPERATION;
                }
            }
            break;
        case OP_COMMAND:
            {
                ES_TRACE_DEBUG("sdr op> [command] operation");
            }
            break;
        default:
            {
                ES_TRACE_DEBUG("sdr op> unknown operation");
                sdr_rt_context.sdr_ft_status = ES_TFTP_ERR_NOT_DEFINED;
            }
            break;
    }

    sdr_rt_context.sdr_ft_status = res;
    sdr_rt_context.is_op_pending = false;
    // USER_CODE_END::onEntry_busy
}
// GEN_OBJ_END::sdr_sm_on_entry_busy



