// Action handlers
// GEN_OBJ_START::sdr_sm_action_poll_device
void sdr_sm_action_poll_device(const uint16_t instance_id, const sState_t * const pSMRoot, const sHSM_EventType_t * const pEvent)
{
    (void) instance_id;
    (void) pSMRoot;
    (void) pEvent;

    // USER_CODE_START::action_poll_device
    es_sys_time_get_req poll_req = es_sys_time_get_req_init_zero;
    es_sys_time_get_res poll_res = es_sys_time_get_res_init_zero;

    poll_res.hdr.stat = ES_STATUS_ERR;

    (void)es_sdr_client_rpc(ES_BOARD_MGR_SERDES_ID, es_board_mgr_rpc_sys_time_get_tag, &poll_req, &poll_res);

    if (ES_STATUS_OK == poll_res.hdr.stat)
    {
        sdr_rt_context.is_boot_complete = true;
    }
    // USER_CODE_END::action_poll_device
}
// GEN_OBJ_END::sdr_sm_action_poll_device

// GEN_OBJ_START::sdr_sm_action_sync_time
void sdr_sm_action_sync_time(const uint16_t instance_id, const sState_t * const pSMRoot, const sHSM_EventType_t * const pEvent)
{
    (void) instance_id;
    (void) pSMRoot;
    (void) pEvent;

    // USER_CODE_START::action_sync_time

    /* Note:    The date and time are formatted as per the requireme
                < UTC Date and/or time formatted with a maxiumum length 25 characters. 
                Simplistic ISO 8601 ASCII/UTF-8 encoded: yyyy-mm-dd hh:mm:ss dd-mm-yyyy hh:mm:ss in any order, .
                A '\' can be used as a delimiter for the date as well. */
    char date_str[11]; // "yyyy-mm-dd"
    char time_str[9];  // "hh:mm:ss"

    // initialize the set time RPC
    sys_time_set_rpc set_time = sys_time_set_rpc_init_zero;
    set_time.payload.req.pl.has_sys_time = true;

    // Note:    Format the date and time using snprintf calls.
    //          The pragma directive is needed to suppress the warning for format truncation.
    //          The warning is suppressed because the format is known and the buffer size is fixed.
    #pragma GCC diagnostic push // push warning state
    #pragma GCC diagnostic ignored "-Wformat-truncation" // ignore format truncation warning
    snprintf(date_str, sizeof(date_str), DATE_FORMAT, sdr_rt_context.sdr_sync_dt.date.year, sdr_rt_context.sdr_sync_dt.date.mon, sdr_rt_context.sdr_sync_dt.date.day);
    snprintf(time_str, sizeof(time_str), TIME_FORMAT, sdr_rt_context.sdr_sync_dt.time.hour, sdr_rt_context.sdr_sync_dt.time.min, sdr_rt_context.sdr_sync_dt.time.sec);

    // format date and time into ISO 8601 ASCII/UTF-8 encoded format as per requirement
    snprintf((char *)set_time.payload.req.pl.sys_time, sizeof(set_time.payload.req.pl.sys_time), "%s %s", date_str, time_str);
    #pragma GCC diagnostic pop // pop warning state

    // dispatch the set_time command
    (void)es_sdr_client_rpc(ES_BOARD_MGR_SERDES_ID, es_board_mgr_rpc_sys_time_set_tag,
                            &set_time.payload.req, &set_time.payload.res);
    sdr_rt_context.is_ready_to_sync = false;

    // .. something to be done with the response status (possibly several retries on failure)

    // USER_CODE_END::action_sync_time
}
// GEN_OBJ_END::sdr_sm_action_sync_time
